def find_sequence(n):
    sequence = []
    for i in range(1, n + 1):
        while True:
            num = i * (i - 1) // 2 + i
            if num % i != num // i:
                sequence.append(num)
                break
    return sequence

for _ in range(int(input())):
    n = int(input())
    sequence = find_sequence(n)
    print(' '.join(map(str, sequence)))

